(* [comment removed for export] *)
Ltac call_svat SV p n i rest lo P sp :=
  let S := fresh "SA" in
  pose proof svat_spec as S; unfold svat_stmt, svat_post, SV_LEAF_STACK, P_SV_INDEX in S;
  callZ (S SV p n i rest lo);
  [ assumption | lia | lia | lia | rewrite ?unsigned_lit by lia; assumption
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add]; lia | lia | assumption | clear S ];
  try match goal with H : rw_cells _ _ SV _, H' : rw_cells _ _ SV _ |- _ => clear H' end;
  lazymatch goal with H : rw_cells _ _ SV _ |- _ => try rename H into FR end;
  lazymatch goal with H : stk _ _ lo _ |- _ => try rename H into ST end;
  lazymatch goal with C : verb_ctx ?m0 _ _ _ _ _ _ _ _ _ |- _ => verb_rebuild_ctx m0 sp P end.

(* [comment removed for export] *)
Ltac call_svrp SV p n k rest lo P sp :=
  let S := fresh "SR" in
  pose proof svrp_spec as S; unfold svrp_stmt, svrp_post, SV_LEAF_STACK, P_SV_REMOVE_PREFIX in S;
  callZ (S SV p n k rest lo);
  [ assumption | lia | lia | lia | rewrite ?unsigned_lit by lia; assumption
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add]; lia | lia | assumption | clear S ];
  try match goal with H : rw_cells _ _ SV (C8 (wz p) :: _), H' : rw_cells _ _ SV _ |- _ => clear H end;
  lazymatch goal with H : rw_cells _ _ SV _ |- _ => try rename H into FR end;
  lazymatch goal with H : stk _ _ lo _ |- _ => try rename H into ST end;
  lazymatch goal with C : verb_ctx ?m0 _ _ _ _ _ _ _ _ _ |- _ => verb_rebuild_ctx m0 sp P end.

Lemma signed_lit_small : forall z, 0 <= z < 2^63 -> bv_signed (Z_to_bv 64 z) = z.
Proof.
  intros z Hz. rewrite zb_signed. rewrite unsigned_lit by lia.
  replace (z <? 2^63) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity.
Qed.

(* [comment removed for export] *)
Ltac vlet :=
  repeat match goal with
  | K : zb ?b = _ |- context [zb ?b =? _] => rewrite K
  | K : zb ?b <> ?c |- context [zb ?b =? ?c] => rewrite (proj2 (Z.eqb_neq _ _) K)
  | K : ?c <> zb ?b |- context [zb ?b =? ?c] => rewrite (proj2 (Z.eqb_neq _ _) (not_eq_sym K))
  end; cbn [Z.eqb Pos.eqb].
Ltac veval2 HBS HC lem := rewrite HBS; rewrite ?zbytes_cons in *; rewrite HC, lem; cbv beta iota; vlet.
(* [comment removed for export] *)
Ltac vlen r := rewrite ?(lzeqb_length r) by (rewrite length_zbytes; cbn; lia).

